// src/ui/splitters.ts
init_define_SMLML_EXAMPLES();
function setupSplitters() {
  const col = document.getElementById("split-col");
  const row = document.getElementById("split-row");
  const workbench = document.getElementById("workbench");
  const root2 = document.documentElement;
  if (col && workbench) {
    onDrag(col, (e) => {
      const rect = workbench.getBoundingClientRect();
      const fb = document.getElementById("filebrowser");
      const fbW = fb && !workbench.classList.contains("fb-collapsed") ? fb.getBoundingClientRect().width + 6 : 0;
      const w = Math.min(Math.max(e.clientX - rect.left - fbW, 200), rect.width - 240);
      root2.style.setProperty("--editor-w", `${w}px`);
    });
  }
  if (row) {
    onDrag(row, (e) => {
      const h = Math.min(Math.max(window.innerHeight - e.clientY, 80), window.innerHeight - 200);
      root2.style.setProperty("--dock-h", `${h}px`);
    });
  }
}
function onDrag(handle, move) {
  handle.addEventListener("pointerdown", (e) => {
    e.preventDefault();
    handle.setPointerCapture(e.pointerId);
    const onMove = (ev) => move(ev);
    const onUp = (ev) => {
      handle.releasePointerCapture(ev.pointerId);
      handle.removeEventListener("pointermove", onMove);
      handle.removeEventListener("pointerup", onUp);
    };
    handle.addEventListener("pointermove", onMove);
    handle.addEventListener("pointerup", onUp);
  });
}

