function formatAstError(res) {
  if (res.details.length === 0) return res.message;
  return [res.message, ...res.details.map((d) => `  ${d}`)].join("\n");
}
function coerceAstResponse(method, raw) {
  if (typeof raw !== "object" || raw === null || !("ok" in raw)) {
    return {
      ok: false,
      kind: "unsupported",
      message: "This language server does not support AST import/export \u2014 update the smlml language server.",
      details: [`${method} returned ${raw === null ? "null" : typeof raw}`]
    };
  }
  return raw;
}
function transportAstResponse(method, err) {
  const detail = err instanceof Error ? err.message : String(err);
  return {
    ok: false,
    kind: "transport",
    message: `The language server did not answer ${method}.`,
    details: [detail]
  };
}
function deliverExport(res) {
  download(new Blob([res.json], { type: "application/json" }), res.suggestedName);
}

// src/lsp/timing.ts
init_define_SMLML_EXAMPLES();
function formatMs(ms) {
  return `${ms.toFixed(0)} ms`;
}
async function timed(log, tag, label, fn, detail) {
  const t0 = performance.now();
  try {
    const value = await fn();
    const suffix = detail ? ` \u2014 ${detail(value)}` : "";
    log.log(tag, `${label}${suffix} in ${formatMs(performance.now() - t0)}`, "op");
    return value;
  } catch (err) {
    log.log(tag, `${label} failed after ${formatMs(performance.now() - t0)}: ${String(err)}`, "warn");
    throw err;
  }
}
function timedSync(log, tag, label, fn, detail) {
  const t0 = performance.now();
  try {
    const value = fn();
    const suffix = detail ? ` \u2014 ${detail(value)}` : "";
    log.log(tag, `${label}${suffix} in ${formatMs(performance.now() - t0)}`, "op");
    return value;
  } catch (err) {
    log.log(tag, `${label} failed after ${formatMs(performance.now() - t0)}: ${String(err)}`, "warn");
    throw err;
  }
}

// src/lsp/analysis-gate.ts
init_define_SMLML_EXAMPLES();
var AnalysisGate = class {
  constructor(deps) {
    this.deps = deps;
  }
  deps;
  pending = 0;
  seq = 0;
  /** True between the first `analyzing` and the matching `settled`. */
  get analyzing() {
    return this.pending > 0;
  }
  /**
   * Announce that `fileCount` documents have just been queued, and resolve with
   * the elapsed milliseconds once the server has worked through them.
   *
   * Resolves — never rejects — even if the ping fails: a pill stuck on
   * "analyzing" because a request timed out is a worse failure than a status
   * computed slightly early. The rejection is reported to the caller via `ok`
   * on the `"settled"` call so it can log the outcome honestly instead of
   * claiming a parse that may not have happened.
   */
  async await(fileCount) {
    const now2 = this.deps.now ?? (() => performance.now());
    const t0 = now2();
    const ticket = ++this.seq;
    this.pending += 1;
    this.deps.onState("analyzing", 0, fileCount, true);
    let ok = true;
    try {
      await this.deps.lsp.sendRequest("smlml/ping", {});
    } catch {
      ok = false;
    }
    this.pending -= 1;
    const elapsed = now2() - t0;
    if (ticket === this.seq) this.deps.onState("settled", elapsed, fileCount, ok);
    return elapsed;
  }
};

